WITH base AS (SELECT *, LOWER(firmware) AS firmware_lower, status_bits - humidity AS status_bits_minus_humidity FROM device_readings WHERE reading_ts > DATE '2025-09-01'), with_prev AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM base), with_gaps AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM with_prev), sessionized AS (SELECT id, device_code, reading_ts, temp_c, pressure, firmware_lower, status_bits_minus_humidity, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY pressure, id) AS dedup_rank FROM sessionized) x WHERE dedup_rank = 1), with_gaps_2 AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM latest), sessionized_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps_2) SELECT * FROM (SELECT id, device_code, pressure, temp_c FROM sessionized_device_readings) src UNPIVOT (val FOR metric_name IN (pressure AS PRESSURE_VAL, temp_c AS TEMP_C_VAL))
